    s = input[1]

    max_len = 1
    # Precompute all possible substrings and their positions
    substr_pos = {}
    for i in range(len(s)):
        for j in range(i + 1, len(s) + 1):
            substr = s[i:j]
            if substr not in substr_pos:
                substr_pos[substr] = []
            substr_pos[substr].append((i, j - 1))

    # Sort substrings by length descending
    substrings = sorted(substr_pos.keys(), key=lambda x: -len(x))

    # DP[i] will store the maximum journey length ending with substring i
    dp = {}
    for substr in substrings:
        dp[substr] = 1
        for prev_substr in substr_pos:
            if len(prev_substr) > len(substr) and substr in prev_substr:
                # Check if there exists a valid sequence of positions
                for (start_prev, end_prev) in substr_pos[prev_substr]:
                    for (start_curr, end_curr) in substr_pos[substr]:
                        if end_prev < start_curr:
                            if prev_substr in dp:
                                if dp[prev_substr] + 1 > dp.get(substr, 0):
                                    dp[substr] = dp[prev_substr] + 1
                                    break
                    else:
                        continue
                    break

    if dp:
        max_len = max(dp.values()) if dp else 1
    print(max_len)

